def string_xor(a: str, b: str) -> str:
    assert isinstance(a, str) and isinstance(b, str), "invalid inputs"  # $_CONTRACT_$
    assert len(a) == len(b), "invalid inputs"  # $_CONTRACT_$
    assert set(a).issubset({"0", "1"}) and set(b).issubset({"0", "1"}), "invalid inputs"  # $_CONTRACT_$
    return "".join("1" if x != y else "0" for x, y in zip(a, b))

def histogram(test):
    assert isinstance(test, str), "invalid inputs"
    words = test.split(" ")
    for word in words:
        if word != "":
            assert len(word) == 1 and word.islower(), "invalid inputs"

    counts = {}
    for w in words:
        if w:
            counts[w] = counts.get(w, 0) + 1

    if not counts:
        return {}

    max_count = max(counts.values())
    return {k: v for k, v in counts.items() if v == max_count}

import math

def max_fill(grid, capacity):
    total = 0
    for row in grid:
        water = sum(row)
        if water:
            total += (water + capacity - 1) // capacity
    return total

def sort_array(arr):
    assert isinstance(arr, list), "invalid inputs"
    assert all(isinstance(x, int) and x >= 0 for x in arr), "invalid inputs"
    return sorted(arr, key=lambda x: (x.bit_count(), x))

def get_closest_vowel(word):
    vowels = set("aeiouAEIOU")
    n = len(word)
    for i in range(n - 2, 0, -1):
        c = word[i]
        if c in vowels and word[i - 1] not in vowels and word[i + 1] not in vowels:
            return c
    return ""

def match_parens(lst):
    def check(s):
        bal = 0
        for ch in s:
            if ch == '(':
                bal += 1
            else:
                bal -= 1
                if bal < 0:
                    return False
        return bal == 0

    a, b = lst
    return "Yes" if (check(a + b) or check(b + a)) else "No"

import heapq

def maximum(arr, k):
    assert type(arr) == list, "invalid inputs"
    assert 1 <= len(arr) <= 1000, "invalid inputs"
    assert all(-1000 <= x <= 1000 for x in arr), "invalid inputs"
    assert type(k) == int, "invalid inputs"
    assert 0 <= k <= len(arr), "invalid inputs"

    if k == 0:
        return []
    return sorted(heapq.nlargest(k, arr))

def solution(lst):
    assert type(lst) == list, "invalid inputs"
    assert all(type(x) == int for x in lst), "invalid inputs"
    assert len(lst) > 0, "invalid inputs"
    return sum(x for i, x in enumerate(lst) if i % 2 == 0 and x % 2 != 0)

def get_odd_collatz(n):
    assert type(n) == int, "invalid inputs"
    assert n > 0, "invalid inputs"

    odds = set()
    while True:
        if n & 1:
            odds.add(n)
            if n == 1:
                break
            n = 3 * n + 1
        else:
            n //= 2
    return sorted(odds)

import re

def valid_date(date):
    if not date:
        return False
    m = re.fullmatch(r'(\d{2})-(\d{2})-(\d{4})', date)
    if not m:
        return False
    month = int(m.group(1))
    day = int(m.group(2))
    if month < 1 or month > 12:
        return False
    if day < 1:
        return False
    if month == 2:
        return day <= 29
    if month in (4, 6, 9, 11):
        return day <= 30
    return day <= 31

def split_words(txt):
    assert type(txt) == str, "invalid inputs"
    assert not txt.startswith(" ") and not txt.startswith(",") and not txt.endswith(" ") and not txt.endswith(","), "invalid inputs"

    if any(ch.isspace() for ch in txt):
        return txt.split()
    if "," in txt:
        return txt.split(",")
    count = 0
    for ch in txt:
        if "a" <= ch <= "z":
            if (ord(ch) - ord("a")) % 2 == 1:
                count += 1
    return count

def is_sorted(lst):
    assert type(lst) == list, "invalid inputs"  # $_CONTRACT_$
    assert all(type(x) == int and x >= 0 for x in lst), "invalid inputs"  # $_CONTRACT_$
    if len(lst) <= 1:
        return True
    prev = lst[0]
    run_len = 1
    for x in lst[1:]:
        if x < prev:
            return False
        if x == prev:
            run_len += 1
            if run_len > 2:
                return False
        else:
            prev = x
            run_len = 1
    return True

def intersection(interval1, interval2):
    a1, b1 = interval1
    a2, b2 = interval2
    s = max(a1, a2)
    e = min(b1, b2)
    if s > e:
        return "NO"
    length = e - s
    if length < 2:
        return "NO"

    if length % 2 == 0:
        return "YES" if length == 2 else "NO"
    if length % 3 == 0:
        return "YES" if length == 3 else "NO"

    i = 5
    w = 2
    while i * i <= length:
        if length % i == 0:
            return "NO"
        i += w
        w = 6 - w
    return "YES"

def prod_signs(arr):
    assert type(arr) == list, "invalid inputs"
    assert all(type(x) == int for x in arr), "invalid inputs"
    if not arr:
        return None
    total_mag = 0
    sign_prod = 1
    for x in arr:
        if x == 0:
            sign_prod = 0
        elif x < 0:
            sign_prod *= -1
        total_mag += abs(x)
    return total_mag * sign_prod

def minPath(grid, k):
    n = len(grid)
    if k == 1:
        mn = grid[0][0]
        for r in range(n):
            row = grid[r]
            for c in range(n):
                v = row[c]
                if v < mn:
                    mn = v
        return [mn]

    dirs = ((1, 0), (-1, 0), (0, 1), (0, -1))

    # Precompute neighbors and value->position
    neighbors = [[None] * n for _ in range(n)]
    pos = [None] * (n * n + 1)
    for r in range(n):
        for c in range(n):
            v = grid[r][c]
            pos[v] = (r, c)
            nb = []
            for dr, dc in dirs:
                rr, cc = r + dr, c + dc
                if 0 <= rr < n and 0 <= cc < n:
                    nb.append((rr, cc))
            neighbors[r][c] = nb

    # Choose smallest starting value (unique)
    start_val = 1
    while True:
        r0, c0 = pos[start_val]
        if r0 is not None:
            break
        start_val += 1

    curr_states = {(r0, c0)}
    result = [start_val]

    for _ in range(2, k + 1):
        # Find minimal next value among all neighbor moves from any current state
        min_next_val = None
        next_positions = []
        for r, c in curr_states:
            for rr, cc in neighbors[r][c]:
                v = grid[rr][cc]
                if min_next_val is None or v < min_next_val:
                    min_next_val = v
                    next_positions = [(rr, cc)]
                elif v == min_next_val:
                    next_positions.append((rr, cc))

        # Deduplicate next states with minimal value
        curr_states = set(next_positions)
        result.append(min_next_val)

    return result

def greatest_common_divisor(a: int, b: int) -> int:
    assert type(a) == int and type(b) == int, "invalid inputs"  # $_CONTRACT_$
    assert a > 0 and b > 0, "invalid inputs"  # $_CONTRACT_$
    while b:
        a, b = b, a % b
    return a

from fractions import Fraction

def tri(n):
    assert type(n) == int, "invalid inputs"
    assert n >= 0, "invalid inputs"

    if n == 0:
        return [1]

    a = [None] * (n + 1)
    a[0] = 1
    a[1] = 3

    for k in range(2, n + 1):
        if k % 2 == 0:
            a[k] = Fraction(1, 1) + Fraction(k, 2)

    for k in range(3, n + 1, 2):
        if k + 1 <= n:
            a[k] = a[k - 1] + a[k - 2] + a[k + 1]
        else:
            a[k] = a[k - 1] + a[k - 2]

    def conv(x):
        if isinstance(x, Fraction) and x.denominator == 1:
            return x.numerator
        return x

    return [conv(x) for x in a]

def is_nested(string):
    assert isinstance(string, str), "invalid inputs"
    assert all(ch == "[" or ch == "]" for ch in string), "invalid inputs"

    depth = 0
    max_depth = 0
    for ch in string:
        if ch == "[":
            depth += 1
            if depth > max_depth:
                max_depth = depth
        else:
            if depth > 0:
                depth -= 1
    return max_depth >= 2

