import re

def fix_spaces(text):
    assert isinstance(text, str), "invalid inputs"  # $_CONTRACT_$
    def repl(m):
        n = len(m.group(0))
        return "_" if n == 1 else "__" if n == 2 else "-"
    return re.sub(r" +", repl, text)

def file_name_check(file_name):
    assert isinstance(file_name, str), "invalid inputs"
    if file_name.count('.') != 1:
        return 'No'
    name, ext = file_name.split('.', 1)
    if not name:
        return 'No'
    first = name[0]
    if not (('a' <= first <= 'z') or ('A' <= first <= 'Z')):
        return 'No'
    digit_count = sum(1 for ch in file_name if '0' <= ch <= '9')
    if digit_count > 3:
        return 'No'
    if ext not in ('txt', 'exe', 'dll'):
        return 'No'
    return 'Yes'

def sum_squares(lst):
    assert type(lst) == list, "invalid inputs"  # $_CONTRACT_$
    assert all(type(x) == int for x in lst), "invalid inputs"  # $_CONTRACT_$
    total = 0
    for i, x in enumerate(lst):
        if i % 3 == 0:
            total += x * x
        elif i % 4 == 0:
            total += x * x * x
        else:
            total += x
    return total

def words_in_sentence(sentence):
    assert isinstance(sentence, str), "invalid inputs"
    assert 1 <= len(sentence) <= 100, "invalid inputs"
    assert "  " not in sentence, "invalid inputs"
    assert all(word.isalpha() for word in sentence.split(" ")), "invalid inputs"

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        d = 3
        while d * d <= n:
            if n % d == 0:
                return False
            d += 2
        return True

    words = sentence.split(" ")
    selected = [w for w in words if is_prime(len(w))]
    return " ".join(selected)

def specialFilter(nums):
    assert type(nums) == list, "invalid inputs"
    assert all(type(x) == int for x in nums), "invalid inputs"

    count = 0
    for n in nums:
        if n <= 10:
            continue
        s = str(abs(n))
        first = ord(s[0]) - 48
        last = ord(s[-1]) - 48
        if (first & 1) and (last & 1):
            count += 1
    return count

def bf(planet1, planet2):
    planets = ("Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune")
    try:
        i1 = planets.index(planet1)
        i2 = planets.index(planet2)
    except ValueError:
        return ()
    if i1 == i2:
        return ()
    lo, hi = (i1, i2) if i1 < i2 else (i2, i1)
    return planets[lo + 1:hi]

