def x_or_y(n, x, y):
    assert type(n) == int, "invalid inputs"  # $_CONTRACT_$
    if n < 2:
        return y
    if n == 2 or n == 3:
        return x
    if n % 2 == 0 or n % 3 == 0:
        return y
    i = 5
    step = 2
    while i * i <= n:
        if n % i == 0:
            return y
        i += step
        step = 6 - step
