def largest_divisor(n: int) -> int:
    assert type(n) == int, "invalid inputs"  # $_CONTRACT_$
    assert n > 1, "invalid inputs"  # $_CONTRACT_$

    if n % 2 == 0:
        return n // 2

    i = 3
    while i * i <= n:
        if n % i == 0:
            return n // i
        i += 2

    return 1

