    return re.split(r'[,\s]+', s.strip())

def choose_num(x, y):
    if x > y:
        return -1
    start = x if x % 2 == 0 else x + 1
    for num in range(start, y + 1, 2):
        if num % 2 == 0:
            continue
    if start > y:
        return -1
    return y if y % 2 == 0 else y - 1

def rounded_avg(n, m):
    if n > m:
        return -1
    total = (n + m) * (m - n + 1) // 2
    count = m - n + 1
    average = total / count
    rounded = round(average)
    return bin(rounded)

def f(n):
