def get_odd_collatz(n):
    assert type(n) == int, "invalid inputs"
    assert n > 0, "invalid inputs"

    sequence = []
    current = n
    while current != 1:
        if current % 2 == 1:
            sequence.append(current)
        if current % 2 == 0:
            current = current // 2
        else:
            current = 3 * current + 1
    sequence.append(1)
    return sorted(set(sequence))

def valid_date(date):
    if not isinstance(date, str):
        return False
    if not date:
        return False
    parts = date.split('-')
    if len(parts) != 3:
        return False
    if not (parts[0].isdigit() and parts[1].isdigit() and parts[2].isdigit()):
        return False
    month = int(parts[0])
    day = int(parts[1])
    year = int(parts[2])
    if month < 1 or month > 12:
        return False
    if month in (1, 3, 5, 7, 8, 10, 12):
        if day < 1 or day > 31:
            return False
    elif month in (4, 6, 9, 11):
        if day < 1 or day > 30:
            return False
    else:
        if day < 1 or day > 29:
            return False
    return True

