def intersection(interval1, interval2):
    assert len(interval1) == 2 and interval1[0] <= interval1[1], "invalid inputs"
    assert all(type(x) == int for x in interval1), "invalid inputs"
    assert len(interval2) == 2 and interval2[0] <= interval2[1], "invalid inputs"
    assert all(type(x) == int for x in interval2), "invalid inputs"

    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])

    if start > end:
        return "NO"

    length = end - start

    if length < 2:
        return "NO"

    for i in range(2, int(length ** 0.5) + 1):
        if length % i == 0:
            return "NO"

    return "YES"

def prod_signs(arr):
    if not arr:
        return None

    product = 1
    magnitude_sum = 0

    for num in arr:
        if num > 0:
            product *= 1
            magnitude_sum += num
        elif num < 0:
            product *= -1
            magnitude_sum += -num
        else:
            product *= 0
            magnitude_sum += 0

    return product * magnitude_sum

def tri(n):
    if n == 0:
        return [1]
    memo = {1: 3}
    def tri_rec(k):
        if k in memo:
            return memo[k]
        if k % 2 == 0:
            val = 1 + k // 2
        else:
            val = tri_rec(k - 1) + tri_rec(k - 2) + tri_rec(k + 1)
        memo[k] = val
        return val
    for i in range(1, n + 1):
        tri_rec(i)
    result = [1]
    for i in range(1, n + 1):
        result.append(memo[i])
    return result

def digits(n):
    product = 1
    has_odd = False
    while n > 0:
        digit = n % 10
        if digit % 2 == 1:
            product *= digit
            has_odd = True
        n //= 10
    return product if has_odd else 0

def is_nested(string):
