def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    groups = paren_string.split()
    result = []
    for group in groups:
        current_depth = 0
        max_depth = 0
        for ch in group:
            if ch == '(':
                current_depth += 1
                if current_depth > max_depth:
                    max_depth = current_depth
            elif ch == ')':
                current_depth -= 1
        result.append(max_depth)
    return result

def derivative(xs: list):
    if len(xs) <= 1:
        return [0]
    result = []
    for i in range(1, len(xs)):
        result.append(xs[i] * i)
    return result

def fibfib(n: int):
    if n == 0 or n == 1:
        return 0
    if n == 2:
        return 1

    a, b, c = 0, 0, 1
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c

def vowels_count(s):
    if not isinstance(s, str):
        raise TypeError("invalid inputs")
    vowels = set('aeiou')
    s_lower = s.lower()
    count = 0
    for i, ch in enumerate(s_lower):
        if ch in vowels:
            count += 1
        elif ch == 'y' and i == len(s_lower) - 1:
            count += 1
    return count

def pluck(arr):
    if not arr:
        return []
    best_val = None
    best_idx = None
    for i, val in enumerate(arr):
        if val % 2 == 0:
            if best_val is None or val < best_val or (val == best_val and i < best_idx):
                best_val = val
                best_idx = i
    if best_val is None:
        return []
    return [best_val, best_idx]

def search(lst):
    from collections import Counter
    freq = Counter(lst)
    candidates = [num for num, count in freq.items() if count >= num]
    if not candidates:
        return -1
    return max(candidates)

def strange_sort_list(lst):
    if not lst:
        return []
    sorted_lst = sorted(lst)
    result = []
    left, right = 0, len(sorted_lst) - 1
    while left <= right:
        result.append(sorted_lst[left])
        left += 1
        if left <= right:
            result.append(sorted_lst[right])
            right -= 1
    return result

import math

def triangle_area(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    s = (a + b + c) / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))
    return round(area, 2)

def will_it_fly(q, w):
    if q != q[::-1]:
        return False
    if sum(q) > w:
        return False
    return True

def total_match(lst1, lst2):
    total1 = sum(len(s) for s in lst1)
    total2 = sum(len(s) for s in lst2)
    if total1 <= total2:
        return lst1
    else:
        return lst2

def is_multiply_prime(a):
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [i for i in range(2, 100) if is_prime(i)]
    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
    return False

def is_simple_power(x, n):
    if n == 1:
        return x == 1
    power = 0
    result = 1
    while result < x:
        result *= n
        power += 1
    return result == x

def iscube(a):
    if a == 0:
        return True
    root = round(abs(a) ** (1/3))
    return root ** 3 == abs(a) and (a > 0 or a == -root ** 3)

def hex_key(num):
    primes = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
    for digit in num:
        if digit in primes:
            count += 1
    return count

from typing import List, Tuple


def sum_product(numbers: List[int]) -> Tuple[int, int]:
    if not numbers:
        return (0, 1)
    total = 0
    product = 1
    for num in numbers:
        total += num
        product *= num
    return (total, product)

def is_happy(s):
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if s[i] == s[i+1] or s[i] == s[i+2] or s[i+1] == s[i+2]:
            return False
    return True

def numerical_letter_grade(grades):
    result = []
    for g in grades:
        if g == 4.0:
            result.append('A+')
        elif g > 3.7:
            result.append('A')
        elif g > 3.3:
            result.append('A-')
        elif g > 3.0:
            result.append('B+')
        elif g > 2.7:
            result.append('B')
        elif g > 2.3:
            result.append('B-')
        elif g > 2.0:
            result.append('C+')
        elif g > 1.7:
            result.append('C')
        elif g > 1.3:
            result.append('C-')
        elif g > 1.0:
            result.append('D+')
        elif g > 0.7:
            result.append('D')
        elif g > 0.0:
            result.append('D-')
        else:
            result.append('E')
    return result

def is_prime(n):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

def prime_length(string):
    return is_prime(len(string))

def solve(N):
    digit_sum = sum(int(d) for d in str(N))
    return bin(digit_sum)[2:]

def add(lst):
    """Given a non-empty list of integers lst. add the even elements that are at odd indices..


    Examples:
        add([4, 2, 6, 7]) ==> 2 
    """
    total = 0
    for i, num in enumerate(lst):
        if i % 2 == 1 and num % 2 == 0:
            total += num
    return total

def anti_shuffle(s):
    if not s:
        return s
    result = []
    word_chars = []
    for ch in s:
        if ch == ' ':
            if word_chars:
                word_chars.sort(key=lambda c: ord(c))
                result.append(''.join(word_chars))
                word_chars = []
            result.append(' ')
        else:
            word_chars.append(ch)
    if word_chars:
        word_chars.sort(key=lambda c: ord(c))
        result.append(''.join(word_chars))
    return ''.join(result)

def get_row(lst, x):
    result = []
    for row_idx, row in enumerate(lst):
        for col_idx, val in enumerate(row):
            if val == x:
                result.append((row_idx, col_idx))
    result.sort(key=lambda t: (t[0], -t[1]))
    return result

def sort_array(array):
    if not array:
        return []
    first = array[0]
    last = array[-1]
    total = first + last
    sorted_arr = sorted(array)
    if total % 2 == 0:
        sorted_arr.reverse()
    return sorted_arr

def encrypt(s):
    if not s:
        return ""
    result = []
    for ch in s:
        base = ord('a')
        offset = (ord(ch) - base + 2 * 2) % 26
        result.append(chr(base + offset))
    return ''.join(result)

from typing import List


def rolling_max(numbers: List[int]) -> List[int]:
    if not numbers:
        return []

    result = []
    current_max = numbers[0]

    for num in numbers:
        if num > current_max:
            current_max = num
        result.append(current_max)

    return result

def next_smallest(lst):
    if len(lst) < 2:
        return None
    unique_sorted = sorted(set(lst))
    if len(unique_sorted) < 2:
        return None
    return unique_sorted[1]

def is_bored(S):
    if not isinstance(S, str):
        raise TypeError("invalid inputs")

    boredom_count = 0
    delimiters = ".?!"

    start = 0
    for i, char in enumerate(S):
        if char in delimiters:
            sentence = S[start:i].strip()
            if sentence.startswith("I "):
                boredom_count += 1
            start = i + 1

    if start < len(S):
        sentence = S[start:].strip()
        if sentence.startswith("I "):
            boredom_count += 1

    return boredom_count

def encode(message):
    vowels = set('aeiouAEIOU')
    result = []
    for ch in message:
        if ch == ' ':
            result.append(' ')
        elif ch.isalpha():
            if ch.lower() in vowels:
                base = ord('a') if ch.islower() else ord('A')
                offset = (ord(ch.lower()) - ord('a') + 2) % 26
                new_ch = chr(base + offset)
                result.append(new_ch.swapcase())
            else:
                result.append(ch.swapcase())
    return ''.join(result)

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(n ** 0.5) + 1):
        if n % i == 0:
            return False
    return True

def skjkasdkd(lst):
    primes = [x for x in lst if is_prime(x)]
    if not primes:
        return 0
    largest_prime = max(primes)
    return sum(int(d) for d in str(largest_prime))

def check_dict_case(dict):
    if not dict:
        return False
    keys = list(dict.keys())
    if not all(isinstance(k, str) for k in keys):
        return False
    lower_keys = all(k.islower() for k in keys)
    upper_keys = all(k.isupper() for k in keys)
    return lower_keys or upper_keys

def count_up_to(n):
    if n < 2:
        return []
    is_prime = [True] * n
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n, i):
                is_prime[j] = False
    return [i for i in range(2, n) if is_prime[i]]

def closest_integer(value):
    try:
        assert isinstance(value, str)
        value = float(value)
    except:
        raise Exception("invalid inputs")
    import math
    assert not (math.isinf(value) or math.isnan(value)), "invalid inputs"

    if value >= 0:
        return int(value + 0.5)
    else:
        return int(value - 0.5)

from typing import List

def has_close_elements(numbers: List[float], threshold: float) -> bool:
    numbers.sort()
    for i in range(len(numbers) - 1):
        if abs(numbers[i] - numbers[i + 1]) <= threshold:
            return True
    return False

def is_palindrome(string: str) -> bool:
    return string == string[::-1]

def make_palindrome(string: str) -> str:
    if not isinstance(string, str):
        raise ValueError("Invalid input: must be a string")

    # Find the longest palindromic suffix
    for i in range(len(string)):
        if is_palindrome(string[i:]):
            return string + string[:i][::-1]
    return string + string[::-1]

def make_a_pile(n):
    pile = []
    for i in range(n):
        if n % 2 == 0:
            pile.append((i + 1) * 2)
        else:
            pile.append((i + 1) * 2 - 1)
    return pile

def words_string(s):
    if not isinstance(s, str):
        raise ValueError("Invalid input: expected a string")

    return s.replace(',', ' ').split()

def choose_num(x, y):
    for num in range(max(x, y), min(x, y) - 1, -1):
        if num % 2 == 0:
            return num
    return -1

def unique_digits(x):
    def has_even_digit(n):
        return any(int(digit) % 2 == 0 for digit in str(n))

    result = [num for num in x if not has_even_digit(num)]
    return sorted(result)

def f(n):
    def factorial(num):
        if num == 0 or num == 1:
            return 1
        result = 1
        for i in range(2, num + 1):
            result *= i
        return result

    def sum_up_to(num):
        return sum(range(1, num + 1))

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_up_to(i))
    return result

def even_odd_palindrome(n):
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    evens = 0
    odds = 0
    for i in range(1, n + 1):
        if is_palindrome(i):
            if i % 2 == 0:
                evens += 1
            else:
                odds += 1
    return (evens, odds)

def count_nums(arr):
    def sum_of_digits(n):
        n = abs(n)
        return sum(int(digit) for digit in str(n))

    return sum(1 for num in arr if sum_of_digits(num) > 0)

def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    sorted_arr = sorted(arr)

    for i in range(n):
        if arr == sorted_arr:
            return True
        arr = [arr[-1]] + arr[:-1]

    return False

def exchange(lst1, lst2):
    evens_in_lst1 = [x for x in lst1 if x % 2 == 0]
    odds_in_lst1 = [x for x in lst1 if x % 2 != 0]
    evens_in_lst2 = [x for x in lst2 if x % 2 == 0]

    if len(odds_in_lst1) <= len(evens_in_lst2):
        return "YES"
    else:
        return "NO"

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not isinstance(test, str) or not test:
        return {}

    words = test.split(" ")
    for word in words:
        if len(word) != 1 or not word.islower():
            return {}

    letter_count = {}
    for letter in words:
        if letter in letter_count:
            letter_count[letter] += 1
        else:
            letter_count[letter] = 1

    max_count = max(letter_count.values(), default=0)
    result = {letter: count for letter, count in letter_count.items() if count == max_count}

    return result

def reverse_delete(s, c):
    result = ''.join([char for char in s if char not in c])
    is_palindrome = result == result[::-1]
    return (result, is_palindrome)

def odd_count(lst):
    def count_odds(s):
        return sum(1 for char in s if int(char) % 2 != 0)

    result = []
    for i, string in enumerate(lst):
        num_odds = count_odds(string)
        result.append("the number of odd elements {}n the str{}ng {} of the {}nput.".format(num_odds, i + 1, num_odds, i + 1))
    return result

import math

def max_fill(grid, capacity):
    total_water = sum([sum(row) for row in grid])
    return math.ceil(total_water / capacity)

def select_words(s, n):
    def count_consonants(word):
        vowels = "aeiouAEIOU"
        return sum(1 for char in word if char.isalpha() and char not in vowels)

    words = s.split()
    result = [word for word in words if count_consonants(word) == n]
    return result

def get_closest_vowel(word):
    vowels = 'aeiouAEIOU'
    length = len(word)

    for i in range(length - 2, 0, -1):
        if word[i] in vowels and word[i + 1:].isalpha():
            return word[i]
    return ""

def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    # Concatenate the two strings and check if they are balanced
    combined = lst[0] + lst[1]
    return 'Yes' if is_balanced(combined) else 'No'

from typing import List, Optional

def longest(strings: List[str]) -> Optional[str]:
    if not strings:
        return None
    max_length = -1
    longest_string = None
    for s in strings:
        if len(s) > max_length:
            max_length = len(s)
            longest_string = s
    return longest_string

import re
from datetime import datetime

def valid_date(date):
    if not isinstance(date, str) or len(date) == 0:
        return False

    pattern = r'^(\d{2})-(\d{2})-(\d{4})$'
    match = re.match(pattern, date)
    if not match:
        return False

    month, day, year = map(int, match.groups())

    if month < 1 or month > 12:
        return False

    days_in_month = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
    if month != 2:
        if day < 1 or day > days_in_month[month - 1]:
            return False
    else:
        if day < 1 or day > 29:
            return False

    try:
        datetime(year, month, day)
        return True
    except ValueError:
        return False

# Example usage:
print(valid_date('03-11-2000')) # => True
print(valid_date('15-01-2012')) # => False
print(valid_date('04-0-2040'))  # => False
print(valid_date('06-04-2020')) # => True
print(valid_date('06/04/2020')) # => False

def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for char in txt:
            if ord('a') <= ord(char) <= ord('z'):
                count += (ord(char) - ord('a')) % 2 == 1
        return count

def is_sorted(lst):
    if len(lst) <= 1:
        return True

    prev = lst[0]
    for num in lst[1:]:
        if num < prev:
            return False
        elif num == prev:
            return False
        prev = num
    return True

def intersection(interval1, interval2):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # Find the intersection of the two intervals
    start_intersection = max(interval1[0], interval2[0])
    end_intersection = min(interval1[1], interval2[1])

    if start_intersection <= end_intersection:
        length_of_intersection = end_intersection - start_intersection + 1
        return "YES" if is_prime(length_of_intersection) else "NO"
    else:
        return "NO"

def prod_signs(arr):
    if not arr:
        return None

    sign_product = 1
    sum_magnitudes = 0

    for num in arr:
        sign_product *= (1 if num > 0 else -1)
        sum_magnitudes += abs(num)

    return sign_product * sum_magnitudes

import heapq

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    # Initialize the priority queue with all starting positions
    pq = []
    for i in range(N):
        for j in range(N):
            heapq.heappush(pq, (grid[i][j], [(i, j)]))

    while pq:
        current_value, path = heapq.heappop(pq)

        if len(path) == k:
            return [grid[x][y] for x, y in path]

        last_x, last_y = path[-1]

        for dx, dy in directions:
            new_x, new_y = last_x + dx, last_y + dy
            if is_valid(new_x, new_y) and (new_x, new_y) not in path:
                new_path = path + [(new_x, new_y)]
                heapq.heappush(pq, (current_value + grid[new_x][new_y], new_path))

    return []

def greatest_common_divisor(a: int, b: int) -> int:
    while b != 0:
        a, b = b, a % b
    return a

def tri(n):
    if n < 0:
        return []

    dp = [0] * (n + 1)
    dp[1] = 3

    for i in range(2, n + 1):
        if i % 2 == 0:
            dp[i] = 1 + i // 2
        else:
            dp[i] = dp[i - 1] + dp[i - 2] + dp[i + 1]

    return [dp[i] for i in range(n + 1)]

def digits(n):
    product = 1
    for digit in str(n):
        if int(digit) % 2 != 0:
            product *= int(digit)
    return product if n > 0 else 0

def is_nested(string):
    stack = []
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack and stack[-1] == '[':
                stack.pop()
            else:
                stack.append(char)
    return len(stack) == 0

def check_if_last_char_is_a_letter(txt):
    if not txt:
        return False
    last_char = txt[-1]
    return last_char.isalpha() and (len(txt) == 1 or txt[len(txt)-2] == ' ')

def compare_one(a, b):
    def to_float(x):
        try:
            return float(str(x).replace(",", "."))
        except ValueError:
            return float('nan')

    a_float = to_float(a)
    b_float = to_float(b)

    if a_float > b_float:
        return a if isinstance(a, (int, float)) else str(a)
    elif b_float > a_float:
        return b if isinstance(b, (int, float)) else str(b)
    else:
        return None

def special_factorial(n):
    def factorial(num):
        if num == 0 or num == 1:
            return 1
        else:
            return num * factorial(num - 1)

    result = 1
    for i in range(1, n + 1):
        result *= factorial(i)
    return result

from typing import List

def all_prefixes(string: str) -> List[str]:
    return [string[:i] for i in range(1, len(string) + 1)]

def fix_spaces(text):
    if not isinstance(text, str):
        raise ValueError("invalid inputs")

    result = []
    for char in text:
        if char == ' ':
            if len(result) > 0 and result[-1] != '_':
                result.append('_')
        else:
            result.append(char)
    return ''.join(result)

def file_name_check(file_name):
    if not isinstance(file_name, str):
        return 'No'

    parts = file_name.split('.')
    if len(parts) != 2:
        return 'No'

    name_part, extension_part = parts
    if not name_part or not (name_part[0].isalpha()):
        return 'No'

    digits = sum(char.isdigit() for char in name_part)
    if digits > 3:
        return 'No'

    valid_extensions = ['txt', 'exe', 'dll']
    if extension_part not in valid_extensions:
        return 'No'

    return 'Yes'

def sum_squares(lst):
    result = 0
    for i, num in enumerate(lst):
        if i % 3 == 0:
            result += num ** 2
        elif i % 4 == 0 and i % 3 != 0:
            result += num ** 3
        else:
            result += num
    return result

def words_in_sentence(sentence):
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(n**0.5) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    prime_length_words = [word for word in words if is_prime(len(word))]
    return ' '.join(prime_length_words)

def order_by_points(nums):
    def digit_sum(n):
        return sum(int(digit) for digit in str(abs(n)))

    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def specialFilter(nums):
    def is_odd(digit):
        return digit % 2 != 0

    def first_and_last_are_odd(num):
        num_str = str(abs(num))
        return is_odd(int(num_str[0])) and is_odd(int(num_str[-1]))

    count = sum(1 for num in nums if num > 10 and first_and_last_are_odd(num))
    return count

