def change_base(x: int, base: int):
    if not (type(x) == int and type(base) == int):
        raise ValueError("invalid inputs")
    if x < 0 or not (2 <= base <= 9):
        raise ValueError("invalid inputs")

    digits = "0123456789"
    if x == 0:
        return "0"

    result = ""
    while x > 0:
        remainder = x % base
        result = digits[remainder] + result
        x //= base

