def starts_one_ends(n):
    if n == 1:
        return 2  # Single-digit numbers starting or ending with 1 are 1 and 10
    elif n == 2:
        return 3  # Two-digit numbers starting or ending with 1 are 10, 11, and 12
    else:
        count = 4  # For n >= 3, the first digit has two choices (1), and the last digit also has two choices (1)
        for _ in range(3, n + 1):
