        vowels = 'aeiouAEIOU'
        if c in vowels:
            index = vowels.index(c)
            return vowels[(index + 2) % len(vowels)]
        return c

    encoded_message = ""
    for char in message:
        if char.isalpha():
            if char.islower():
                encoded_char = char.upper()
            else:
                encoded_char = char.lower()
            encoded_char = shift_vowel(encoded_char)
            encoded_message += encoded_char
        else:
            encoded_message += char
    return encoded_message

