    return sum(1 for x in arr if sum_of_digits(x) > 0)

def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    sorted_arr = sorted(arr)

    for i in range(n):
        if arr[i:] + arr[:i] == sorted_arr:
            return True

    return False

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    # Split the input string into words
    words = test.split(" ")

    # Initialize a dictionary to count occurrences of each letter
    counts = {}

    # Count each letter's occurrences
    for word in words:
        if word != "":
            if word in counts:
                counts[word] += 1
            else:
                counts[word] = 1

    # Find the maximum occurrence count
    max_count = max(counts.values()) if counts else 0

    # Create a dictionary of letters with the maximum occurrence count
    result = {letter: count for letter, count in counts.items() if count == max_count}

    return result

def reverse_delete(s, c):
    # Remove all characters in s that are present in c
    result = ''.join(char for char in s if char not in c)

    # Check if the result string is a palindrome
    is_palindrome = result == result[::-1]

    return (result, is_palindrome)

def minSubArraySum(nums):
    min_sum = float('inf')
    current_sum = 0

    for num in nums:
        current_sum += num
        if current_sum < min_sum:
            min_sum = current_sum
        if current_sum > 0:
            current_sum = 0

    return min_sum

def max_fill(grid, capacity):
    total_water_units = sum(sum(row) for row in grid)
    return math.ceil(total_water_units / capacity)

def select_words(s, n):
    vowels = set('aeiouAEIOU')
    words = s.split()
    result = []

    for word in words:
        consonant_count = sum(1 for char in word if char.isalpha() and char not in vowels)
        if consonant_count == n:
            result.append(word)

    return result

def get_closest_vowel(word):
    vowels = "aeiouAEIOU"
    length = len(word)

    for i in range(length - 2, 0, -1):
        if word[i] in vowels and word[i-1] not in vowels and word[i+1] not in vowels:
            return word[i]

    return ""

def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for char in s:
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    str1, str2 = lst
    return 'Yes' if is_balanced(str1 + str2) or is_balanced(str2 + str1) else 'No'

def get_odd_collatz(n):
    odd_numbers = []
    while n != 1:
        if n % 2 == 1:
            odd_numbers.append(n)
        n = 3 * n + 1 if n % 2 else n // 2
    odd_numbers.append(1)  # Add the final number in the sequence, which is 1
    return sorted(odd_numbers)

def valid_date(date):
    if not date:
        return False

    parts = date.split('-')
    if len(parts) != 3:
        return False

    try:
        month, day, year = map(int, parts)
    except ValueError:
        return False

    if month < 1 or month > 12:
        return False

    if day < 1:
        return False

    if month in {1, 3, 5, 7, 8, 10, 12} and day > 31:
        return False
    elif month in {4, 6, 9, 11} and day > 30:
        return False
    elif month == 2 and day > 29:
        return False

    return True

def split_words(txt):
    if ' ' in txt:
        return txt.split()
    elif ',' in txt:
        return txt.split(',')
    else:
        count = sum(1 for char in txt if char.islower() and (ord(char) - ord('a')) % 2 == 0)
        return count

def is_sorted(lst):
    if len(lst) <= 1:
        return True

    previous = lst[0]
    duplicate_count = 1

    for i in range(1, len(lst)):
        if lst[i] < previous:
            return False
        elif lst[i] == previous:
            duplicate_count += 1
            if duplicate_count > 2:
                return False
        else:
            duplicate_count = 1
        previous = lst[i]

    return True

def intersection(interval1, interval2):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    start1, end1 = interval1
    start2, end2 = interval2

    # Calculate the intersection
    intersect_start = max(start1, start2)
    intersect_end = min(end1, end2)

    # Check if there is an intersection
    if intersect_start <= intersect_end:
        length = intersect_end - intersect_start + 1
        if is_prime(length):
            return "YES"

    return "NO"

def prod_signs(arr):
    if not arr:
        return None

    product_of_signs = 1
    sum_of_magnitudes = 0

    for num in arr:
        if num == 0:
            return 0
        product_of_signs *= (1 if num > 0 else -1)
        sum_of_magnitudes += abs(num)

    return sum_of_magnitudes * product_of_signs

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    def dfs(x, y, path):
        if len(path) == k:
            return path

        min_path = None
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                new_path = dfs(nx, ny, path + [grid[nx][ny]])
                if min_path is None or new_path < min_path:
                    min_path = new_path

        return min_path

    min_result = None
    for i in range(N):
        for j in range(N):
            path = dfs(i, j, [grid[i][j]])
            if min_result is None or path < min_result:
                min_result = path

    return min_result

def tri(n):
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    sequence = [0] * (n + 1)

    for i in range(n + 1):
        if i == 0:
            sequence[i] = 3
        elif i % 2 == 0:
            sequence[i] = 1 + i // 2
        else:
            if i == 1:
                sequence[i] = 3
            else:
                sequence[i] = sequence[i - 1] + sequence[i - 2] + (sequence[i + 1] if i < n else 0)

    return sequence

def digits(n):
    product = 1
    has_odd_digit = False

    while n > 0:
        digit = n % 10
        if digit % 2 != 0:
            product *= digit
            has_odd_digit = True
        n //= 10

    return product if has_odd_digit else 0

def is_nested(string):
    depth = 0
    max_depth = 0

    for char in string:
        if char == '[':
            depth += 1
            max_depth = max(max_depth, depth)
        elif char == ']':
            depth -= 1

        # If depth goes negative, it means there are unmatched closing brackets
        if depth < 0:
            return False

    # Check if there was at least one nested bracket
    return max_depth > 1 and depth == 0

import math

def sum_squares(lst):
    return sum(math.ceil(x) ** 2 for x in lst)

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,
    """

    def parse_value(value):
        if isinstance(value, str):
            return float(value.replace(",", "."))
        return float(value)

    parsed_a = parse_value(a)
    parsed_b = parse_value(b)

    if parsed_a > parsed_b:
        return a
    elif parsed_b > parsed_a:
        return b
    else:
        return None

def special_factorial(n):
    def factorial(x):
        if x == 1 or x == 0:
            return 1
        else:
            return x * factorial(x - 1)

    result = 1
    for i in range(1, n + 1):
        result *= factorial(i)

    return result

def fix_spaces(text):
    result = []
    consecutive_spaces = 0

    for char in text:
        if char == ' ':
            consecutive_spaces += 1
        else:
            if consecutive_spaces > 2:
                result.append('-')
            elif consecutive_spaces > 0:
                result.extend(['_'] * consecutive_spaces)
            result.append(char)
            consecutive_spaces = 0

    # Handle trailing spaces
    if consecutive_spaces > 2:
        result.append('-')
    elif consecutive_spaces > 0:
        result.extend(['_'] * consecutive_spaces)

    return ''.join(result)

def file_name_check(file_name):
    parts = file_name.split('.')

    # Check if there is exactly one dot
    if len(parts) != 2:
        return 'No'

    name_part, extension_part = parts

    # Check if the substring before the dot is not empty and starts with a letter
    if not name_part or not name_part[0].isalpha():
        return 'No'

    # Check if there are more than three digits in the name part
    if sum(c.isdigit() for c in name_part) > 3:
        return 'No'

    # Check if the extension is one of the allowed types
    if extension_part not in ['txt', 'exe', 'dll']:
        return 'No'

    return 'Yes'

def sum_squares(lst):
    total = 0
    for i, x in enumerate(lst):
        if i % 3 == 0:
            total += x ** 2
        elif i % 4 == 0:
            total += x ** 3
        else:
            total += x
    return total

def words_in_sentence(sentence):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    words = sentence.split()
    prime_length_words = [word for word in words if is_prime(len(word))]
    return ' '.join(prime_length_words)

def order_by_points(nums):
