        return sum(int(digit) for digit in str(abs(n)))

    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def specialFilter(nums):
    def is_odd_digit(digit):
        return digit in {'1', '3', '5', '7', '9'}

    count = 0
    for num in nums:
        if num > 10:
            num_str = str(abs(num))
            if is_odd_digit(num_str[0]) and is_odd_digit(num_str[-1]):
                count += 1
    return count

def get_max_triples(n):
    a = [i * i - i + 1 for i in range(1, n + 1)]
    count_mod = [0, 0, 0]

    for num in a:
        count_mod[num % 3] += 1

    total_triples = 0

    # Case 1: All three numbers have the same remainder when divided by 3
    for mod in range(3):
        if count_mod[mod] >= 3:
            total_triples += (count_mod[mod] * (count_mod[mod] - 1) * (count_mod[mod] - 2)) // 6

    # Case 2: All three numbers have different remainders when divided by 3
    total_triples += count_mod[0] * count_mod[1] * count_mod[2]

    return total_triples

def bf(planet1, planet2):
    planets = ["Mercury", "Venus", "Earth", "Mars", "Jupiter", "Saturn", "Uranus", "Neptune"]

    if planet1 not in planets or planet2 not in planets:
        return ()

    index1 = planets.index(planet1)
    index2 = planets.index(planet2)

    if index1 < index2:
        return tuple(planets[index1 + 1:index2])
    else:
        return tuple(planets[index2 + 1:index1])

def x_or_y(n, x, y):
    if n <= 1:
        return y
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return y
    return x

def cycpattern_check(a, b):
    if len(b) > len(a):
