    for i in range(len(b)):
        rotated_b = b[i:] + b[:i]
        if rotated_b in a:
            return True

    return False

def right_angle_triangle(a, b, c):
    sides = sorted([a, b, c])
    return abs(sides[2]**2 - (sides[0]**2 + sides[1]**2)) < 1e-9

def find_max(words):
    def unique_char_count(word):
        return len(set(word))

    max_word = ""
    max_unique_chars = 0

    for word in words:
        unique_count = unique_char_count(word)
        if (unique_count > max_unique_chars) or (unique_count == max_unique_chars and word < max_word):
            max_word = word
            max_unique_chars = unique_count

    return max_word

def eat(number, need, remaining):
    if need <= remaining:
        total_eaten = number + need
        carrots_left = remaining - need
    else:
        total_eaten = number + remaining
        carrots_left = 0

    return [total_eaten, carrots_left]

def do_algebra(operator, operand):
    expression = str(operand[0])
    for i in range(len(operator)):
        expression += f" {operator[i]} {operand[i + 1]}"

    return eval(expression)

def solve(s):
    if any(c.isalpha() for c in s):
        return ''.join(c.swapcase() if c.isalpha() else c for c in s)
    else:
        return s[::-1]

def largest_divisor(n: int) -> int:
    """ For a given number n, find the largest number that divides n evenly, smaller than n
    >>> largest_divisor(15)
    5
    """
    for i in range(n - 1, 0, -1):
        if n % i == 0:
            return i

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    return ''.join(char.lower() if char.isupper() else char.upper() for char in string)

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for operation in operations:
        balance += operation
        if balance < 0:
            return True
    return False

def is_prime(n):
    """Return true if a given number is prime, and false otherwise."""
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def fizz_buzz(n: int):
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def prime_fib(n: int):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                return False
        return True

    fib_sequence = [0, 1]
    prime_fibs = []

    while len(prime_fibs) < n:
        next_fib = fib_sequence[-1] + fib_sequence[-2]
        fib_sequence.append(next_fib)
        if is_prime(next_fib):
            prime_fibs.append(next_fib)

    return prime_fibs[n - 1]

def pairs_sum_to_zero(l):
    seen = set()
    for num in l:
        if -num in seen:
            return True
        seen.add(num)
    return False

def change_base(x: int, base: int) -> str:
    if x == 0:
        return "0"

    digits = []
    while x > 0:
        remainder = x % base
        digits.append(str(remainder))
        x = x // base

    # The digits are collected in reverse order
    digits.reverse()

    return ''.join(digits)

def fib4(n: int):
    if n == 0:
        return 0
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    elif n == 3:
        return 0

    # Initialize the first four numbers of the sequence
    fib4_values = [0, 0, 2, 0]

    # Compute the sequence iteratively up to n
    for i in range(4, n + 1):
        next_value = sum(fib4_values)
        fib4_values.pop(0)  # Remove the oldest value
        fib4_values.append(next_value)  # Add the new value

    return fib4_values[-1]

def modp(n: int, p: int):
    """Return 2^n modulo p (be aware of numerics)."""
    return pow(2, n, p)

def decode_shift(s: str):
    """
    takes as input string encoded with encode_shift function. Returns decoded string.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

def below_threshold(l: list, t: int):
    """Return True if all numbers in the list l are below threshold t."""
    return all(x < t for x in l)

def fib(n: int) -> int:
    if n <= 1:
        return n
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, a + b
    return b

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '<':
            balance += 1
        elif char == '>':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime.
    >>> largest_prime_factor(13195)
    29
    >>> largest_prime_factor(2048)
    2
    """
    def is_prime(a):
        return not (a < 2 or any(a % x == 0 for x in range(2, int(a ** 0.5) + 1)))

    largest_factor = None
    # Check for number of 2s that divide n
    while n % 2 == 0:
        largest_factor = 2
        n //= 2

    # n must be odd at this point, so a skip of 2 (i.e., i = i + 2) can be used
    for i in range(3, int(n ** 0.5) + 1, 2):
        while n % i == 0:
            largest_factor = i
            n //= i

    # If n is a prime number greater than 2
    if n > 2:
        largest_factor = n

    return largest_factor

def correct_bracketing(brackets: str):
    balance = 0
    for char in brackets:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def fibfib(n: int) -> int:
    if n == 0 or n == 1:
        return 0
    elif n == 2:
        return 1

    a, b, c = 0, 0, 1
    for _ in range(3, n + 1):
        a, b, c = b, c, a + b + c
    return c

def vowels_count(s):
