    count = sum(1 for char in s if char in vowels)

    if s and s[-1].lower() == 'y':
        count += 1

    return count

def pluck(arr):
    min_even_value = float('inf')
    min_index = -1

    for index, value in enumerate(arr):
        if value % 2 == 0 and value < min_even_value:
            min_even_value = value
            min_index = index

    if min_index == -1:
        return []

    return [min_even_value, min_index]

def search(lst):
    from collections import Counter

    freq = Counter(lst)
    max_val = -1

    for num, count in freq.items():
        if count >= num:
            max_val = max(max_val, num)

    return max_val

import math

def triangle_area(a, b, c):
    if a + b <= c or a + c <= b or b + c <= a:
        return -1
    s = (a + b + c) / 2
    area = math.sqrt(s * (s - a) * (s - b) * (s - c))
    return round(area, 2)

def total_match(lst1, lst2):
    total_chars_lst1 = sum(len(s) for s in lst1)
    total_chars_lst2 = sum(len(s) for s in lst2)

    if total_chars_lst1 < total_chars_lst2:
        return lst1
    else:
        return lst2

def is_multiply_prime(a):
    def is_prime(n):
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    primes = [i for i in range(2, a) if is_prime(i)]

    for i in range(len(primes)):
        for j in range(i, len(primes)):
            for k in range(j, len(primes)):
                if primes[i] * primes[j] * primes[k] == a:
                    return True
    return False

def is_simple_power(x, n):
    if x < 1 or n < 1:
        return False
    if n == 1:
        return x == 1
    power = 1
    while power < x:
        power *= n
    return power == x

def iscube(a):
    if a < 0:
        a = -a
    cube_root = round(a ** (1/3))
    return cube_root ** 3 == a

def hex_key(num):
    prime_hex_digits = {'2', '3', '5', '7', 'B', 'D'}
    return sum(1 for digit in num if digit in prime_hex_digits)

def decimal_to_binary(decimal):
    if decimal == 0:
        return "db0db"

    binary = ""
    while decimal > 0:
        binary = str(decimal % 2) + binary
        decimal //= 2

    return f"db{binary}db"

def is_happy(s):
    if len(s) < 3:
        return False
    for i in range(len(s) - 2):
        if s[i] == s[i+1] or s[i] == s[i+2] or s[i+1] == s[i+2]:
            return False
    return True

def numerical_letter_grade(grades):
    def get_letter_grade(gpa):
        if gpa == 4.0:
            return 'A+'
        elif gpa > 3.7:
            return 'A'
        elif gpa > 3.3:
            return 'A-'
        elif gpa > 3.0:
            return 'B+'
        elif gpa > 2.7:
            return 'B'
        elif gpa > 2.3:
            return 'B-'
        elif gpa > 2.0:
            return 'C+'
        elif gpa > 1.7:
            return 'C'
        elif gpa > 1.3:
            return 'C-'
        elif gpa > 1.0:
            return 'D+'
        elif gpa > 0.7:
            return 'D'
        elif gpa > 0.0:
            return 'D-'
        else:
            return 'E'

    return [get_letter_grade(gpa) for gpa in grades]

def prime_length(string):
    """Write a function that takes a string and returns True if the string
    length is a prime number or False otherwise
    Examples
    prime_length('Hello') == True
    prime_length('abcdcba') == True
    prime_length('kittens') == True
    prime_length('orange') == False
    """

    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    return is_prime(len(string))

def add(lst):
    """Given a non-empty list of integers lst. add the even elements that are at odd indices..

    Examples:
        add([4, 2, 6, 7]) ==> 2 
    """
    return sum(x for i, x in enumerate(lst) if i % 2 == 1 and x % 2 == 0)

def get_row(lst, x):
    result = []
    for i, row in enumerate(lst):
        indices = [j for j, val in enumerate(row) if val == x]
        indices.sort(reverse=True)
        for index in indices:
            result.append((i, index))
    return result

def sort_array(array):
    if not array:
        return []

    sum_first_last = array[0] + array[-1]
    if sum_first_last % 2 == 0:
        return sorted(array, reverse=True)
    else:
        return sorted(array)

def next_smallest(lst):
    if len(set(lst)) < 2:
        return None
    unique_lst = sorted(set(lst))
    return unique_lst[1]

def any_int(x, y, z):
    if not all(isinstance(v, int) for v in [x, y, z]):
        return False
    return x + y == z or x + z == y or y + z == x

def encode(message):
    vowels = 'aeiouAEIOU'
    shift = 2
    encoded_message = []

    for char in message:
        if char.isalpha():
            if char in vowels:
                # Find the vowel's position and replace it with the letter 2 places ahead
                new_char = chr(((ord(char.lower()) - ord('a') + shift) % 26) + ord('a'))
                # Preserve the original case
                if char.isupper():
                    new_char = new_char.upper()
                encoded_message.append(new_char)
            else:
                # Swap the case of non-vowel letters
                encoded_message.append(char.swapcase())
        else:
            # Keep spaces as they are
            encoded_message.append(char)

    return ''.join(encoded_message)

def skjkasdkd(lst):
