def f(n):
    def factorial(x):
        return x * factorial(x - 1) if x > 1 else 1

    def sum_to_x(x):
        return x * (x + 1) // 2

    result = []
    for i in range(1, n + 1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to_x(i))

    return result

def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    sorted_arr = sorted(arr)

    for i in range(n):
        if arr == sorted_arr:
            return True
        arr.insert(0, arr.pop())

    return False

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}

    words = test.split(" ")
    letter_counts = {}

    for word in words:
        if word:
            letter_counts[word] = letter_counts.get(word, 0) + 1

    max_count = max(letter_counts.values(), default=0)
    return {letter: count for letter, count in letter_counts.items() if count == max_count}

def reverse_delete(s, c):
    result = ''.join([char for char in s if char not in c])
    return (result, result == result[::-1])

def max_fill(grid, capacity):
