    elif ',' in txt:
        return txt.split(',')
    else:
        return sum(1 for char in txt if char.islower() and (ord(char) - ord('a')) % 2 == 0)

def is_sorted(lst):
    if len(lst) < 2:
        return True
    prev = lst[0]
    count = 1
    for num in lst[1:]:
        if num == prev:
            count += 1
            if count > 1:
                return False
        else:
            prev = num
            count = 1
        if num < prev:
            return False
    return True

def intersection(interval1, interval2):
    start = max(interval1[0], interval2[0])
    end = min(interval1[1], interval2[1])
    if start > end:
        return "NO"
    length = end - start + 1
    if length < 2:
        return "NO"
    for i in range(2, int(length**0.5) + 1):
        if length % i == 0:
            return "NO"
    return "YES"

def prod_signs(arr):
    if not arr:
        return None
    sign_product = 1
    magnitude_sum = 0
    for num in arr:
        if num == 0:
            return 0
        elif num < 0:
            sign_product *= -1
        magnitude_sum += abs(num)
    return sign_product * magnitude_sum

def minPath(grid, k):
    N = len(grid)
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def dfs(x, y, path):
        if len(path) == k:
            return path
        min_path = None
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < N and 0 <= ny < N:
                new_path = dfs(nx, ny, path + [grid[nx][ny]])
                if min_path is None or (new_path and (min_path is None or new_path < min_path)):
                    min_path = new_path
        return min_path

    min_path = None
    for i in range(N):
        for j in range(N):
            path = dfs(i, j, [grid[i][j]])
            if min_path is None or (path and (min_path is None or path < min_path)):
                min_path = path
    return min_path

def tri(n):
    if n < 0:
        raise ValueError("n must be a non-negative integer")

    if n == 0:
        return [1]
    elif n == 1:
        return [1, 3]

    tribonacci = [1, 3, 2]
    for i in range(3, n + 1):
        if i % 2 == 0:
            tribonacci.append(1 + i / 2)
        else:
            tribonacci.append(tribonacci[i - 1] + tribonacci[i - 2] + tribonacci[i + 1])
    return tribonacci

def digits(n):
    product = 1
    has_odd = False
    for digit in str(n):
        d = int(digit)
        if d % 2 == 1:
            product *= d
            has_odd = True
    return product if has_odd else 0

def is_nested(s):
    stack = []
    nested = False
    for char in s:
        if char == '[':
            stack.append(char)
        elif char == ']' and stack:
            stack.pop()
            if stack:
                nested = True
    return nested and not stack

