def eulerian_num(n, m):
    if not (isinstance(n, int) and isinstance(m, int) and n >= 0 and m >= 0):
        raise ValueError("invalid inputs")

    if m == 0:
        return 1
    elif m == n:
        return 0
    else:
        return (n - m) * eulerian_num(n - 1, m - 1) + (m + 1) * eulerian_num(n - 1, m)

