def search(arr):
    low = 0
    high = len(arr) - 1

    while low < high:
        mid = (low + high) // 2

        if mid % 2 == 0:
            if arr[mid] == arr[mid + 1]:
                low = mid + 2
            else:
                high = mid
        else:
            if arr[mid] == arr[mid - 1]:
                low = mid + 1
            else:
                high = mid - 1

    return arr[low]

def amicable_numbers_sum(limit):
    def sum_of_divisors(n):
        return sum(i for i in range(1, n // 2 + 1) if n % i == 0)

    total_sum = 0
    for a in range(2, limit + 1):
        b = sum_of_divisors(a)
        if a != b and sum_of_divisors(b) == a:
            total_sum += a
    return total_sum

