def magic_square_test(my_matrix):
    n = len(my_matrix)
    if not (isinstance(my_matrix, list) and len(my_matrix) > 0 and all(isinstance(row, list) for row in my_matrix) and len(my_matrix[0]) > 0 and all(len(row) == len(my_matrix[0]) for row in my_matrix) and all(isinstance(item, (int, float)) for row in my_matrix for item in row)):
        return False

    magic_sum = sum(my_matrix[0])

    # Check sums of rows
    for i in range(n):
        if sum(my_matrix[i]) != magic_sum:
            return False

    # Check sums of columns
    for j in range(n):
        col_sum = 0
        for i in range(n):
            col_sum += my_matrix[i][j]
        if col_sum != magic_sum:
            return False

    # Check sum of the primary diagonal
    diag_sum1 = 0
    for i in range(n):
        diag_sum1 += my_matrix[i][i]
    if diag_sum1 != magic_sum:
        return False

    # Check sum of the secondary diagonal
    diag_sum2 = 0
    for i in range(n):
        diag_sum2 += my_matrix[i][n - 1 - i]
    if diag_sum2 != magic_sum:
        return False

    return True

