    for item, count in frequency.items():
        if count > max_count:
            max_count = count
            max_item = item
    return max_item

def reverse_vowels(s):
    vowels = 'aeiouAEIOU'
    left, right = 0, len(s) - 1
    s = list(s)

    while left < right:
        if s[left] in vowels and s[right] in vowels:
            s[left], s[right] = s[right], s[left]
            left += 1
            right -= 1
        elif s[left] not in vowels:
            left += 1
        else:
            right -= 1

    return ''.join(s)

