def max_sub_array_sum_repeated(a, n, k):
    def max_sub_array_sum(arr):
        max_so_far = float('-inf')
        max_ending_here = 0
        for num in arr:
            max_ending_here += num
            if max_so_far < max_ending_here:
                max_so_far = max_ending_here
            if max_ending_here < 0:
                max_ending_here = 0
        return max_so_far

    # Calculate the maximum subarray sum for the original array repeated k times
    total_sum = max_sub_array_sum(a) * k

    # Handle the case where k is 1 (no repetition needed)
    if k == 1:
        return total_sum

    # Calculate the maximum subarray sum for the prefix and suffix arrays
    prefix_sum = [0] * (2 * n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + a[i]
    for i in range(n):
        prefix_sum[i + n + 1] = prefix_sum[i + n] + a[i]

    # Find the maximum subarray sum using Kadane's algorithm on the prefix sums
    max_so_far = float('-inf')
    max_ending_here = 0
    for i in range(2 * n):
        max_ending_here += prefix_sum[i] - prefix_sum[(i - n) % (n + 1)]
        if max_so_far < max_ending_here:
            max_so_far = max_ending_here
        if max_ending_here < 0:
            max_ending_here = 0

    # Add the maximum subarray sum of the prefix and suffix arrays to the total sum
    return total_sum + max(max_so_far, max_sub_array_sum(a))

