def max_aggregate(stdata):
    from collections import defaultdict

    if not isinstance(stdata, list) or not all(isinstance(x, tuple) for x in stdata) or not all(len(x) == 2 for x in stdata) or not all(isinstance(x[1], (int, float)) for x in stdata):
