def max_sum_increasing_subseq(a, n, index, k):
    if not (isinstance(a, list) and all(isinstance(x, (int, float)) for x in a) and isinstance(n, int) and n == len(a) and isinstance(index, int) and 0 <= index < n and isinstance(k, int) and index < k < n):
        raise ValueError("invalid inputs")

    # Create a list to store the maximum sum of increasing subsequence ending at each index
    dp = [0] * n
    for i in range(n):
        dp[i] = a[i]
        for j in range(i):
            if a[j] < a[i]:
                dp[i] = max(dp[i], dp[j] + a[i])

    # Find the maximum sum of increasing subsequence including the kth element
    result = 0
    for i in range(index, n):
        if a[i] > a[index]:
            result = max(result, dp[i] + a[index])

    return result

