def cal_sum(n):
    if not isinstance(n, int):
        raise ValueError("invalid inputs")

    def perrin(k):
        if k == 0:
            return 3
        elif k == 1:
            return 0
        elif k == 2:
            return 2
        else:
            return perrin(k - 2) + perrin(k - 3)

    total_sum = sum(perrin(i) for i in range(n + 1))
    return total_sum

