def catalan_number(num):
    if not isinstance(num, int) or num < 0:
        raise ValueError("invalid inputs")

    def binomial_coeff(n, k):
        if k > n - k:
            k = n - k
        res = 1
        for i in range(k):
            res *= (n - i)
            res //= (i + 1)
        return res

    catalan = [0] * (num + 1)
    catalan[0], catalan[1] = 1, 1

    for i in range(2, num + 1):
        catalan[i] = binomial_coeff(2*i - 2, i - 1) // i

    return catalan[num]

