def find_first_occurrence(A, x):
    left, right = 0, len(A) - 1
    while left <= right:
        mid = (left + right) // 2
        if A[mid] == x and (mid == 0 or A[mid - 1] != x):
            return mid
        elif A[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1

def sum_Of_Subarray_Prod(arr):
    def subarray_products(arr):
        n = len(arr)
        result = []
        for i in range(n):
            prod = 1
            for j in range(i, n):
                prod *= arr[j]
                result.append(prod)
        return result

    subarray_products_result = subarray_products(arr)
    return sum(subarray_products_result)

