def toggle_middle_bits(n):
    if not isinstance(n, int) or n < 0:
        raise ValueError("Invalid input")

    bit_length = n.bit_length()
    if bit_length <= 2:
        return ~n & ((1 << bit_length) - 1)

    mask = (1 << (bit_length - 2)) - 1
    masked_number = n & mask
    toggled_bits = ~masked_number & mask
    result = (n & (~mask | (1 << (bit_length - 1)))) | toggled_bits

    return result

def left_insertion(a, value):
    left = 0
    right = len(a)

    while left < right:
        mid = (left + right) // 2
        if a[mid] < value:
            left = mid + 1
        else:
            right = mid

    return left

