def check_min_heap(arr):
    def is_valid_parent(i):
        if left_child_index := 2 * i + 1 < len(arr):
            if arr[left_child_index] < arr[i]:
                return False
        if right_child_index := 2 * i + 2 < len(arr):
            if arr[right_child_index] < arr[i]:
                return False
        return True

    for i in range(len(arr)):
        if not is_valid_parent(i):
            return False
    return True

def jacobsthal_num(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1

    a, b = 0, 1
    for _ in range(2, n + 1):
        next_jacobsthal = a + 2 * b
        a, b = b, next_jacobsthal

    return b

