def is_polite(n):
    def is_polite_helper(num):
        count = 0
        for i in range(1, num + 1):
            if num % i != 0:
                count += 1
        return count

    polite_count = 0
    num = 1
    while True:
        if is_polite_helper(num) > 2 * (num ** 0.5):
            polite_count += 1
        if polite_count == n:
            return num
        num += 1

