def check_expression(exp):
    stack = []
    matching_bracket = {')': '(', '}': '{', ']': '['}

    for char in exp:
        if char in matching_bracket.values():
            stack.append(char)
        elif char in matching_bracket.keys():
            if not stack or stack[-1] != matching_bracket[char]:
                return False
            stack.pop()

    return len(stack) == 0

