def find_sum(arr):
    unique_elements = set()
    duplicates = set()

    for num in arr:
        if num in duplicates:
            continue
        if num in unique_elements:
            unique_elements.remove(num)
            duplicates.add(num)
        else:
            unique_elements.add(num)

    return sum(unique_elements)

