def search(arr):
    left, right = 0, len(arr) - 1

    while left < right:
        mid = left + (right - left) // 2

        # Ensure mid is even for comparison
        if mid % 2 == 1:
            mid -= 1

        # Compare pairs
        if arr[mid] == arr[mid + 1]:
            left = mid + 2
        else:
            right = mid

    return arr[left]

