def find_length(string):
    max_diff = 0
    current_sum = 0
    min_sum = 0

    for char in string:
        if char == '0':
            current_sum += 1
        else:
            current_sum -= 1

        max_diff = max(max_diff, current_sum - min_sum)
        min_sum = min(min_sum, current_sum)

    return max_diff

def sum(a, b):
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    common_divisors_sum = 0
    for i in range(1, gcd(a, b) + 1):
        if a % i == 0 and b % i == 0:
            common_divisors_sum += i

    return common_divisors_sum

