def is_Sub_Array(A, B):
    m = len(A)
    n = len(B)

    # A[] is smaller than B[] so can't be a sub array
    if m < n:
        return False

    for i in range(m - n + 1):
        j = 0
        while j < n and A[i + j] == B[j]:
            j += 1

        # If all elements of B[] matched, then B[] is subarray of A[]
        if j == n:
            return True

    # If we reach here, then B[] is not a sub array of A[]
    return False

def last_Digit_Factorial(n):
    if n == 0 or n == 1:
        return 1
    elif n >= 5:
        return 0
    else:
        result = 1
        for i in range(2, int(n) + 1):
            result = (result * (i % 10)) % 10
        return result

