def largest_subset(a):
    n = len(a)
    a.sort()

    # Initialize the dp array where dp[i] represents the size of the largest subset ending with a[i]
    dp = [1] * n

    # Fill the dp array
    for i in range(1, n):
        for j in range(i):
            if a[i] % a[j] == 0:
                dp[i] = max(dp[i], dp[j] + 1)

    # The size of the largest subset is the maximum value in the dp array
    return max(dp)

