def is_sublist(l, s):
    if not s:
        return True
    if len(s) > len(l):
        return False

    for i in range(len(l)):
        if l[i] == s[0]:
            j = 1
            while j < len(s):
                if i + j >= len(l) or l[i + j] != s[j]:
                    break
                j += 1
            if j == len(s):
                return True
    return False

