def search(arr):
    n = len(arr)
    if n == 1:
        return arr[0]

    left, right = 0, n - 1

    while left < right:
        mid = left + (right - left) // 2

        # Check if the mid is at the single element
        if mid % 2 == 1:
            mid -= 1

        # If the pair is not equal, the single element is on the left side
        if arr[mid] != arr[mid + 1]:
            right = mid
        else:
            left = mid + 2

    return arr[left]

